DROP TABLE IF EXISTS fe_article CASCADE; DROP TABLE IF EXISTS fe_author CASCADE; DROP TABLE IF EXISTS fe_log CASCADE;
DROP FUNCTION IF EXISTS search_authors(text); DROP FUNCTION IF EXISTS author_full(fe_author); DROP FUNCTION IF EXISTS add_author(text);
DROP FUNCTION IF EXISTS author_count(fe_author, int); DROP FUNCTION IF EXISTS author_articles(fe_author); DROP FUNCTION IF EXISTS volatile_fn(text);
DROP FUNCTION IF EXISTS scalar_fn(int); DROP FUNCTION IF EXISTS log_rows(); DROP FUNCTION IF EXISTS "Bad-Name"(); DROP FUNCTION IF EXISTS sess_fn(json, text); DROP FUNCTION IF EXISTS sess_bad(text); DROP FUNCTION IF EXISTS overloaded(int); DROP FUNCTION IF EXISTS overloaded(text); DROP FUNCTION IF EXISTS author_sess(fe_author, json);
CREATE TABLE fe_author(id serial primary key, name text, bio text);
CREATE TABLE fe_article(id serial primary key, title text, author_id int references fe_author(id));
CREATE TABLE fe_log(id serial primary key, msg text);
CREATE FUNCTION search_authors(q text) RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author WHERE name ilike ('%' || q || '%') $$ LANGUAGE sql STABLE;
CREATE FUNCTION author_full(a fe_author) RETURNS text AS $$ SELECT a.name || ' ' || coalesce(a.bio,'') $$ LANGUAGE sql STABLE;
CREATE FUNCTION author_count(a fe_author, n int) RETURNS int AS $$ SELECT n $$ LANGUAGE sql STABLE;
CREATE FUNCTION author_articles(a fe_author) RETURNS SETOF fe_article AS $$ SELECT * FROM fe_article WHERE author_id = a.id $$ LANGUAGE sql STABLE;
CREATE FUNCTION author_sess(a fe_author, hasura_session json) RETURNS text AS $$ SELECT hasura_session->>'x-hasura-role' $$ LANGUAGE sql STABLE;
CREATE FUNCTION add_author(n text) RETURNS SETOF fe_author AS $$ INSERT INTO fe_author(name) VALUES (n) RETURNING * $$ LANGUAGE sql VOLATILE;
CREATE FUNCTION scalar_fn(x int) RETURNS int AS $$ SELECT x $$ LANGUAGE sql STABLE;
CREATE FUNCTION overloaded(x int) RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author $$ LANGUAGE sql STABLE;
CREATE FUNCTION log_rows() RETURNS SETOF fe_log AS $$ SELECT * FROM fe_log $$ LANGUAGE sql STABLE;
CREATE FUNCTION "Bad-Name"() RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author $$ LANGUAGE sql STABLE;
CREATE FUNCTION sess_fn(hasura_session json, q text) RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author $$ LANGUAGE sql STABLE;
CREATE FUNCTION sess_bad(s text) RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author $$ LANGUAGE sql STABLE;
CREATE FUNCTION overloaded(x text) RETURNS SETOF fe_author AS $$ SELECT * FROM fe_author $$ LANGUAGE sql STABLE;
